package main

import "fmt"

// Ordered admits any type whose underlying type supports the < operator.
// The ~ means "any type whose underlying type is this".
type Ordered interface {
	~int | ~int64 | ~float64 | ~string
}

// Map transforms []T into []U via f. T and U are independent type params.
func Map[T, U any](s []T, f func(T) U) []U {
	out := make([]U, len(s)) // pre-size: one slot per input
	for i, v := range s {
		out[i] = f(v)
	}
	return out
}

// Filter keeps elements for which keep returns true.
func Filter[T any](s []T, keep func(T) bool) []T {
	out := make([]T, 0, len(s))
	for _, v := range s {
		if keep(v) {
			out = append(out, v)
		}
	}
	return out
}

// Min works for any ordered type because the constraint permits <.
func Min[T Ordered](a, b T) T {
	if a < b {
		return a
	}
	return b
}

func main() {
	nums := []int{1, 2, 3, 4}
	squares := Map(nums, func(n int) int { return n * n }) // T,U=int inferred
	evens := Filter(nums, func(n int) bool { return n%2 == 0 })
	labels := Map(nums, func(n int) string { return fmt.Sprintf("#%d", n) }) // U=string

	fmt.Println(squares)
	fmt.Println(evens)
	fmt.Println(labels)
	fmt.Println(Min(9, 4), Min("go", "rust"))
}

