type Set[T comparable] map[T]struct{}

func NewSet[T comparable](items ...T) Set[T] {
	s := make(Set[T], len(items))
	for _, it := range items {
		s.Add(it)
	}
	return s
}

func (s Set[T]) Add(v T) {
	s[v] = struct{}{} // empty struct uses zero bytes of value storage
}

func (s Set[T]) Contains(v T) bool {
	_, ok := s[v] // comma-ok reports presence
	return ok
}

func main() {
	s := NewSet("a", "b", "a")
	fmt.Println(len(s))            // 2 (duplicate collapsed)
	fmt.Println(s.Contains("b"))  // true
	fmt.Println(s.Contains("z"))  // false
}

