package main

import "fmt"

type List[T any] struct {
	items []T
}

// A package-level function CAN declare both T and U.
func Map[T, U any](l List[T], f func(T) U) []U {
	out := make([]U, len(l.items))
	for i, v := range l.items {
		out[i] = f(v)
	}
	return out
}

func main() {
	l := List[int]{items: []int{1, 2, 3}}
	labels := Map(l, func(n int) string { return fmt.Sprintf("n%d", n) })
	fmt.Println(labels)
}

func Reduce[T, U any](s []T, init U, f func(acc U, x T) U) U {
	acc := init
	for _, v := range s {        // left fold
		acc = f(acc, v)          // caller supplies all type-specific logic
	}
	return acc
}

// Usage:
//   sum := Reduce([]int{1,2,3}, 0, func(a, x int) int { return a + x })      // 6
//   csv := Reduce([]string{"a","b"}, "", func(a, x string) string {
//       if a == "" { return x }
//       return a + "," + x
//   })                                                                        // "a,b"
